pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: a user with zero credit
        address user = address(0x1);
        vm.deal(user, 1 ether);

        // User calls withdrawAll() directly (no deposit first, so credit[user] == 0)
        vm.prank(user);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // Reference: call succeeds (oCredit>0 false, no Ether sent)
        // Bug: call reverts due to require(callResult) when sending 0 Ether to EOA without receive()
        assertTrue(success, "withdrawAll() should succeed with zero credit");
    }
}

