pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address malicious;

    function setUp() public {
        c = new C();
        malicious = address(new Malicious());
    }

    function testRegression_property() public {
        // Deposit 1 ether as the malicious contract
        vm.deal(malicious, 1 ether);
        vm.prank(malicious);
        c.deposit{value: 1 ether}();

        // Attempt withdrawAll; the reference reverts due to failed call,
        // the bug does not revert and updates state.
        // For the reference, credit[malicious] should still be 1 ether.
        // For the bug, credit[malicious] is 0.
        vm.prank(malicious);
        c.withdrawAll();

        // Assert: reference has credit[malicious] > 0, bug has 0.
        assertTrue(c.credit(malicious) > 0);
    }
}

contract Malicious {
    receive() external payable {
        revert("rejecting ether");
    }
}

