pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address malicious = address(0x123);
        vm.deal(malicious, 1 ether);
        vm.prank(malicious);
        c.deposit{value: 1 ether}();

        // Prepare malicious recipient that reverts on receive
        address recipient = address(0x456);
        vm.etch(recipient, hex"60206000fd"); // REVERT opcode

        vm.prank(recipient);
        // Set credit for recipient to something > 0 by having recipient call deposit
        vm.prank(recipient);
        c.deposit{value: 1 ether}();

        // Now have malicious try to withdraw - but recipient will reject
        vm.startPrank(malicious);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        vm.stopPrank();

        // After the failed withdrawal, check that credit[malicious] was properly preserved
        // In reference: require(callResult) reverts so credit stays unchanged (does not execute credit[msg.sender]=0)
        // In bug: credit[msg.sender]=0 still executes even though transfer failed
        assertTrue(c.credit(malicious) > 0);
    }
}

