pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();
        // alice is now a contract that rejects ether
        vm.prank(address(0x456));
        c.deposit{value: 0 ether}(); // just to have another user
        // Prepare a malicious contract that rejects ether
        Rejector rejector = new Rejector();
        vm.deal(address(rejector), 1 ether);
        vm.prank(address(rejector));
        c.deposit{value: 1 ether}();
        // Now try withdraw for rejector - should revert in reference, succeed in bug
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(!ok); // reference reverts (ok false), bug does not (ok true)
    }
}

contract Rejector {
    fallback() external payable {
        revert("reject");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();

        // deploy a malicious contract that rejects ether
        MaliciousRejecter rejecter = new MaliciousRejecter();
        vm.deal(address(rejecter), 0);
        vm.startPrank(address(rejecter));
        c.deposit{value: 1 ether}();
        uint creditBefore = c.credit(address(rejecter));
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // In reference, withdrawAll reverts => ok == false, credit remains > 0, balance remains
        // In bug, withdrawAll succeeds => ok == true, credit becomes 0
        assertTrue(ok == false, "Bug: withdrawal succeeded but should have reverted");
        assertTrue(c.credit(address(rejecter)) == creditBefore, "Bug: credit changed");
    }
}

contract MaliciousRejecter {
    receive() external payable {
        revert("I reject ether");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address rejecter = address(new RejectEther());
        vm.deal(rejecter, 2 ether);
        vm.prank(rejecter);
        c.deposit{value: 2 ether}();

        vm.prank(rejecter);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        uint creditAfter = c.credit(rejecter);
        if (success) {
            // Buggy version: credit set to 0
            assertTrue(creditAfter == 0);
        } else {
            // Reference version: revert, credit unchanged
            assertTrue(creditAfter == 2 ether);
        }
    }
}

contract RejectEther {
    receive() external payable {
        revert();
    }
}
